queries.query:
find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { date_trunc("day", pe.startts) as day, count() as builds, round(100.0 * count(case when pe.status = "SUCCESS" then 1 end) / nullif(count(), 0), 1) as success_rate_pct }
| group_by day | order_by day asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { case when pe.status = "SUCCESS" then "Success" when pe.status = "FAILED" then "Failed" when pe.status = "ABORTED" then "Aborted" when pe.status = "EXPIRED" then "Expired" when pe.status = "IGNOREFAILED" then "Ignore-failed" else "Other" end as outcome, count() as builds }
| group_by outcome | order_by builds desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week, case when pe.status = "SUCCESS" then "Success" when pe.status = "FAILED" then "Failed" when pe.status = "ABORTED" then "Aborted" when pe.status = "EXPIRED" then "Expired" when pe.status = "IGNOREFAILED" then "Ignore-failed" else "Other" end as outcome, count() as builds }
| group_by week, outcome | order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate {
    pe.projectidentifier as project,
    count(case when pe.startts >= ago(30d) then 1 end) as last_30d,
    count(case when pe.startts < ago(30d) and pe.startts >= ago(60d) then 1 end) as prior_30d,
    count(case when pe.startts >= ago(30d) then 1 end) - count(case when pe.startts < ago(30d) and pe.startts >= ago(60d) then 1 end) as change
  }
| group_by project
| having last_30d + prior_30d > 0
| order_by last_30d desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { pe.projectidentifier as project, pe.status as status, count() as builds }
| group_by project, status

find view "view:ci:stage_execution_summary" se | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = se.plan_execution_id | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate} and ${infra_filter_predicate} and ${os_filter_predicate} | filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate { se.os_type as os, se.resource_class as resource_class, round(avg(se.minutes_stage_duration), 2) as avg_stage_minutes }
| group_by os, resource_class | order_by os asc

find view "view:ci:stage_execution_summary" se | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = se.plan_execution_id | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate} and ${infra_filter_predicate} and ${os_filter_predicate} | filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate { se.stage_name as stage, round(avg(se.minutes_stage_duration), 2) as avg_minutes }
| group_by stage | order_by avg_minutes desc | limit 12

with p9 as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate} | filter pe.build_duration > 0
  | aggregate { pe.pipelineidentifier as pp, percentile(pe.build_duration, 90) as p90 }
  | group_by pp
), runs as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
  | select { pe.planexecutionid as exec_id, pe.orgidentifier as org, pe.projectidentifier as project,
      pe.pipelineidentifier as pipeline, pe.status as status, pe.startts as started, pe.build_duration as bd,
      pe.moduleinfo_branch_name as branch }
)
find runs | join p9 on p9.pp = runs.pipeline | filter runs.bd > p9.p90
| select { runs.started as started, runs.exec_id as exec_id, runs.org as org, runs.project as project,
    runs.pipeline as pipeline, runs.branch as branch, runs.status as status,
    round(runs.bd / 1000.0, 0) as duration, round(p9.p90 / 1000.0, 0) as pipeline_p90,
    round(100.0 * (runs.bd - p9.p90) / p9.p90, 1) as pct_over_p90 }
| order_by pct_over_p90 desc | limit 50

with runs as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
  | select { pe.projectidentifier as project, pe.pipelineidentifier as pipeline, pe.startts as ts, pe.status as status,
      lag(pe.status) over (partition by pe.pipelineidentifier order by pe.startts) as prev_status }
), fails as (
  find runs | filter status = "FAILED" and (prev_status is null or prev_status != "FAILED")
  | select { project, pipeline, ts as fail_ts }
), recov as (
  find runs | filter status = "SUCCESS" | select { pipeline as p2, ts as ok_ts }
), pairs as (
  find fails | join recov on recov.p2 = fails.pipeline | filter recov.ok_ts > fails.fail_ts
  | aggregate { fails.project as project, fails.pipeline as pipeline, fails.fail_ts as fail_ts, min(recov.ok_ts) as ok_ts }
  | group_by project, pipeline, fail_ts
) find pairs | aggregate { avg(date_diff(fail_ts, ok_ts, "second")) as mttr_s }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week, round(100.0 * count(case when pe.status = "FAILED" then 1 end) / nullif(count(), 0), 1) as failure_rate_pct,
    count(case when pe.status = "FAILED" then 1 end) as failed_builds }
| group_by week | order_by week asc

find view "view:pipeline:stage_execution_failure" sf | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = sf.plan_execution_id
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { coalesce(nullif(sf.failure_type, ""), "UNCLASSIFIED") as failure_type, count() as failures }
| group_by failure_type | order_by failures desc

with runs as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
  | select { pe.projectidentifier as project, pe.pipelineidentifier as pipeline, pe.startts as ts, pe.status as status,
      lag(pe.status) over (partition by pe.pipelineidentifier order by pe.startts) as prev_status }
), fails as (
  find runs | filter status = "FAILED" and (prev_status is null or prev_status != "FAILED")
  | select { project, pipeline, ts as fail_ts }
), recov as (
  find runs | filter status = "SUCCESS" | select { pipeline as p2, ts as ok_ts }
), pairs as (
  find fails | join recov on recov.p2 = fails.pipeline | filter recov.ok_ts > fails.fail_ts
  | aggregate { fails.project as project, fails.pipeline as pipeline, fails.fail_ts as fail_ts, min(recov.ok_ts) as ok_ts }
  | group_by project, pipeline, fail_ts
)
find pairs
| aggregate { project, pipeline, count() as incidents,
    avg(date_diff(fail_ts, ok_ts, "second")) as mttr,
    max(date_diff(fail_ts, ok_ts, "second")) as worst_recovery,
    max(ok_ts) as last_recovered }
| group_by project, pipeline | order_by mttr desc

with r as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
  | select { pe.projectidentifier as project, pe.pipelineidentifier as pipeline, pe.status as s,
      lag(pe.status) over (partition by pe.pipelineidentifier order by pe.startts) as ps }
)
find r
| aggregate { project, pipeline, count() as runs,
    count(case when s = "FAILED" then 1 end) as failed,
    count(case when ps in ["SUCCESS", "FAILED"] and s in ["SUCCESS", "FAILED"] and s != ps then 1 end) as status_flips,
    round(100.0 * count(case when ps in ["SUCCESS", "FAILED"] and s in ["SUCCESS", "FAILED"] and s != ps then 1 end) / nullif(count() - 1, 0), 1) as flip_rate }
| group_by project, pipeline | having status_flips > 0 | order_by flip_rate desc

find view "ci:dim_scm" scm | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = scm.plan_execution_id
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { concat(scm.provider, " (", scm.host, ")") as provider, count() as builds }
| group_by provider | order_by builds desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { coalesce(pe.trigger_type, "UNKNOWN") as trigger_type, count() as builds }
| group_by trigger_type | order_by builds desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week, coalesce(pe.trigger_type, "UNKNOWN") as trigger_type, count() as builds }
| group_by week, trigger_type | order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week,
    distinct_count(case when pe.moduleinfo_author_id is not null and pe.moduleinfo_author_id not in ["NA", ""] then pe.moduleinfo_author_id end) as active_developers,
    count() as builds }
| group_by week | order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { case when date_diff(date_trunc("week", pe.startts), pe.startts, "day") < 1 then "1 Mon" when date_diff(date_trunc("week", pe.startts), pe.startts, "day") < 2 then "2 Tue" when date_diff(date_trunc("week", pe.startts), pe.startts, "day") < 3 then "3 Wed" when date_diff(date_trunc("week", pe.startts), pe.startts, "day") < 4 then "4 Thu" when date_diff(date_trunc("week", pe.startts), pe.startts, "day") < 5 then "5 Fri" when date_diff(date_trunc("week", pe.startts), pe.startts, "day") < 6 then "6 Sat" else "7 Sun" end as weekday, case when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 3 then "00-03" when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 6 then "03-06" when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 9 then "06-09" when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 12 then "09-12" when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 15 then "12-15" when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 18 then "15-18" when date_diff(date_trunc("day", pe.startts), pe.startts, "hour") < 21 then "18-21" else "21-24" end as hour_band, count() as builds }
| group_by weekday, hour_band

find view "ci:stage_execution_summary_ci_table" ct | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = ct.planexecutionid | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { concat(ct.infratype, " / ", ct.ostype) as infrastructure, round(sum(ct.stagebuildtime) / 60000.0, 1) as build_minutes }
| group_by infrastructure | order_by build_minutes desc

find view "view:ci:stage_execution_summary" se | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = se.plan_execution_id | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate} and ${infra_filter_predicate} and ${os_filter_predicate}
| aggregate { se.os_type as os, se.resource_class as resource_class, round(sum(se.ci_credits), 0) as credits }
| group_by os, resource_class | order_by os asc

find view "view:ci:stage_execution_summary" se | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = se.plan_execution_id | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate} and ${infra_filter_predicate} and ${os_filter_predicate} | filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate { se.infrastructure_type as infrastructure, se.os_type as os, round(sum(se.hours_stage_duration), 3) as stage_hours }
| group_by infrastructure, os

find view "ci:fct_builds" b | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = b.plan_execution_id
| filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { date_trunc("week", b.start_ts) as week,
    round(sum(b.stage_build_time) / 60000.0, 1) as build_minutes,
    count(case when b.is_optimized then 1 end) as optimized_builds }
| group_by week | order_by week asc

find entity "pipeline:pipeline" p | filter p.deleted = false | filter p.last_updated_at >= cast(${start_time} as timestamp) and p.last_updated_at <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate}
| aggregate { case when date_diff(p.last_updated_at, now(), "day") < 7 then "1. < 1 week"
    when date_diff(p.last_updated_at, now(), "day") < 30 then "2. 1-4 weeks"
    when date_diff(p.last_updated_at, now(), "day") < 90 then "3. 1-3 months"
    else "4. > 3 months" end as last_change, count() as pipelines }
| group_by last_change | order_by last_change asc

find entity "pipeline:pipeline" p | filter p.deleted = false | filter p.created_at >= cast(${start_time} as timestamp) and p.created_at <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate}
| aggregate { date_trunc("month", p.created_at) as month, p.store_type as store_type, count() as pipelines }
| group_by month, store_type | order_by month asc

with runs as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp)
  | aggregate { pe.orgidentifier as ro, pe.projectidentifier as rp, pe.pipelineidentifier as rpl, count() as builds,
      round(100.0 * count(case when pe.status = "SUCCESS" then 1 end) / nullif(count(), 0), 1) as success_rate, max(pe.startts) as last_run }
  | group_by ro, rp, rpl
)
find entity "pipeline:pipeline" p | filter p.deleted = false | filter p.last_updated_at >= cast(${start_time} as timestamp) and p.last_updated_at <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate}
| left join runs on runs.ro = p.org_identifier and runs.rp = p.project_identifier and runs.rpl = p.identifier
| select {
    p.org_identifier as org, p.project_identifier as project, p.identifier as pipeline, p.name as name,
    p.store_type as store_type, p.enable_dag as dag_enabled, p.is_draft as draft,
    p.created_at as created, p.last_updated_at as updated,
    coalesce(runs.builds, 0) as ci_builds, runs.success_rate as success_rate, runs.last_run as last_ci_run,
    runs.builds is not null as ran_in_window
  }
| order_by ci_builds desc | limit 200

find entity "pipeline:template" tp | filter tp.deleted = false | filter tp.last_updated_at >= cast(${start_time} as timestamp) and tp.last_updated_at <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| aggregate { tp.template_entity_type as template_type, count() as templates }
| group_by template_type | order_by templates desc

find entity "pipeline:template" tp | filter tp.deleted = false | filter tp.last_updated_at >= cast(${start_time} as timestamp) and tp.last_updated_at <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select {
    tp.template_entity_type as template_type, tp.name as name, tp.identifier as identifier,
    tp.version_label as version, tp.is_stable_template as stable, tp.child_type as child_type,
    tp.template_scope as scope,
    tp.modules as modules,
    tp.store_type as store_type, tp.last_updated_at as updated
  }
| order_by updated desc | limit 200

find view "view:sto:scan" s | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = s.plan_execution_id | inner join view "view:pipeline:step_execution" st on st.plan_execution_id = s.plan_execution_id and st.step_identifier = s.step_identifier | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { st.step_type as scanner, count() as scans }
| group_by scanner | order_by scans desc

find view "opa:policy_evaluation_result_view" o | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = o.plan_execution_id | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate { concat(o.policyset_name, " - ", o.policy_status) as policy_result, count() as results }
| group_by policy_result | order_by results desc

find view "view:sto:scan" s | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = s.plan_execution_id | inner join view "view:pipeline:step_execution" st on st.plan_execution_id = s.plan_execution_id and st.step_identifier = s.step_identifier | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate {
    pe.startts as started, pe.planexecutionid as exec_id, pe.orgidentifier as org, pe.projectidentifier as project,
    pe.pipelineidentifier as pipeline, pe.status as status,
    count() as scans, distinct_count(st.step_type) as scanners,
    count(case when s.status != "Succeeded" then 1 end) as failed_scans,
    round(sum(st.duration) / 1000.0, 0) as scan_time
  }
| group_by started, exec_id, org, project, pipeline, status | order_by started desc | limit 100

find view "opa:policy_evaluation_result_view" o | inner join view "ci:pipeline_execution_summary_ci" pe on pe.planexecutionid = o.plan_execution_id | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate} and ${branch_filter_predicate} and ${status_filter_predicate} and ${trigger_filter_predicate}
| aggregate {
    o.policy_name as policy, o.policyset_name as policy_set, o.policy_status as result,
    o.evaluation_action as action, coalesce(nullif(o.policy_severity, ""), "-") as severity,
    count() as evaluations, distinct_count(pe.planexecutionid) as ci_runs, max(o.evaluation_created) as last_evaluated
  }
| group_by policy, policy_set, result, action, severity | order_by evaluations desc
